record VlanInfo(int vid, int pcp, int etherType) {}
static VlanInfo vlan(byte[] f) {
  int tpid = ((f[12] & 0xff) << 8) | (f[13] & 0xff);
  if (tpid != 0x8100 && tpid != 0x88A8) return new VlanInfo(-1, -1, tpid);
  int tci = ((f[14] & 0xff) << 8) | (f[15] & 0xff);
  int et = ((f[16] & 0xff) << 8) | (f[17] & 0xff);
  return new VlanInfo(tci & 0x0FFF, tci >>> 13, et);
}
// Dla QinQ (0x88A8) wewnętrzny znacznik zaczyna się od bajtu 16 — można wywołać rekurencyjnie z przesunięciem.
